			<?php
			$numero = 1;
			$base_top = 21.8938; 
			$incremento_y = 1.933;

			foreach ($productos as $fila) {
				$current_top = $base_top + (($numero - 1) * $incremento_y);
				$left_no = ($numero >= 10) ? "3.88em" : "4.06em";
				
				echo '<div class="pdf24_01" style="left:'.$left_no.'; top:'.$current_top.'em;"><span class="pdf24_24 pdf24_14 pdf24_37">'.$numero.'</span></div>';
				echo '<div class="pdf24_01" style="left:6.50em; top:'.$current_top.'em;"><span class="pdf24_24 pdf24_14 pdf24_37">'.htmlspecialchars($fila['codigo']).'</span></div>';
				echo '<div class="pdf24_01" style="left:12.00em; top:'.$current_top.'em;"><span class="pdf24_24 pdf24_14 pdf24_37">'.htmlspecialchars($fila['nombre']).'</span></div>';
				echo '<div class="pdf24_01" style="left:34.75em; top:'.$current_top.'em;"><span class="pdf24_24 pdf24_14 pdf24_37">'.htmlspecialchars($fila['marca']).'</span></div>';
				echo '<div class="pdf24_01" style="left:40.52em; top:'.$current_top.'em;"><span class="pdf24_24 pdf24_14 pdf24_37">'.htmlspecialchars($fila['modelo']).'</span></div>';
				echo '<div class="pdf24_01" style="left:46.00em; top:'.$current_top.'em;"><span class="pdf24_24 pdf24_14 pdf24_37">'.htmlspecialchars($fila['stock']).'</span></div>';
				echo '<div class="pdf24_01" style="left:50.50em; top:'.$current_top.'em;"><span class="pdf24_24 pdf24_14 pdf24_37">______</span></div>';

				$numero++;
			}
